import json, subprocess, sys, copy

BASE_CFG = {
    "early": False, "overlap": "reject", "buffer_packets": 2, "idle_ms": 0,
    "max_streams_bidi": 4, "max_streams_uni": 4, "max_stream_data": 32,
    "max_data": 64, "crypto_limit": 32, "sent": {"I": [], "H": [], "A": []},
}

def cfg(**kw):
    c = copy.deepcopy(BASE_CFG)
    c.update(kw)
    return c

def trace(tid, events, **kw):
    return {"id": tid, "config": cfg(**kw), "events": events}

def req(traces):
    return {"version": 1, "traces": traces}

def run(doc):
    if isinstance(doc, bytes):
        inp = doc
    elif isinstance(doc, str):
        inp = doc.encode()
    else:
        inp = json.dumps(doc).encode()
    p = subprocess.run([sys.executable, "-I", "/app/submission/entry.py"],
                       input=inp, stdout=subprocess.PIPE,
                       stderr=subprocess.PIPE, cwd="/app/submission")
    err = p.stderr.decode()
    if err.strip():
        print("STDERR:", err[:800])
    if p.returncode != 0:
        print("NONZERO EXIT", p.returncode)
        return None
    out = p.stdout.decode()
    try:
        return json.loads(out)
    except Exception:
        print("BAD OUTPUT JSON:", out[:300])
        return None

def is_invalid(parsed):
    return parsed == {"error": "INVALID_INPUT"}

def show(x):
    print(json.dumps(x, indent=1))

PASS = 0
FAIL = 0
def check(name, got, want):
    global PASS, FAIL
    if got == want:
        PASS += 1
    else:
        FAIL += 1
        print("FAIL %s" % name)
        print("  got :", json.dumps(got))
        print("  want:", json.dumps(want))

def expect_invalid(name, doc):
    global PASS, FAIL
    got = run(doc)
    if is_invalid(got):
        PASS += 1
    else:
        FAIL += 1
        print("FAIL(invalid) %s -> %s" % (name, json.dumps(got)[:400]))

def summary():
    print("passed=%d failed=%d" % (PASS, FAIL))
    return FAIL
EOF
